/**
 * Writes api/_site.ts: the chat's system prompt and the links an AI answer may keep, generated from
 * src/content. The Node.js function then imports one plain file instead of the whole content tree.
 * Run after changing content: npm run chat:site (tests/chatServer.test.ts fails if it is stale).
 */
import { writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { buildSystemPrompt, siteLinks } from '../../src/chat/prompt';
import { content } from '../../src/content';

export function siteModule(): string {
  return [
    '// Generated by scripts/chat/site.ts from src/content. Do not edit; run `npm run chat:site`.',
    `export const SYSTEM_PROMPT = ${JSON.stringify(buildSystemPrompt(content))};`,
    `export const SITE_LINKS: readonly string[] = ${JSON.stringify([...siteLinks(content)].sort(), null, 2)};`,
    '',
  ].join('\n');
}

if (process.argv[1] && resolve(process.argv[1]) === resolve(import.meta.dirname, 'site.ts')) {
  const out = resolve(import.meta.dirname, '../../api/_site.ts');
  writeFileSync(out, siteModule());
  console.log(`wrote ${out}`);
}
